// Explanations describe the simulated rule used, not calibrated confidence scores.
const riskNotes={deadline:['Unverified deadline','The draft promises a Friday deadline without checking whether you can meet it.'],availability:['Unverified availability','The draft confirms a meeting slot without your approval.'],calendar:['Calendar and intent check','This message asks you to commit to a specific meeting slot. The local demo calendar may show a conflict, but only you can confirm availability.'],approval:['Unverified approval','The draft approves spending without confirming review or authority.'],promise:['Unverified launch promise','The draft treats a proposed date as an approved commitment.'],commitment:['Unverified commitment','The draft accepts a task without confirming your decision.'],preference:['Unverified preference','The draft chooses on your behalf without asking your preference.'],delivery:['Unverified delivery','The draft guarantees a delivery date that the demo cannot validate.']};
function riskMarkup(message,kind){let pattern={deadline:/finish (?:the report|it) by Friday/ig,availability:/available (?:for the client call )?at 3 PM|3 PM works(?: perfectly for me)?/ig,calendar:/23 November(?: 2026)?(?: at)? (?:14:00|2 PM)|Monday at 2 PM/ig,approval:/approve (?:the revised )?(?:budget|quotation)|Approved/ig,promise:/launch (?:on )?2 December|confirm (?:the )?2 December/ig,commitment:/lead (?:the onboarding workshop|it)/ig,preference:/purple header|Purple, please/ig,delivery:/delivery (?:will be completed |confirmed )?by 28 November|arrive by 28 November/ig}[kind];if(!pattern)return escapeHtml(message);let output='',pos=0,m;while((m=pattern.exec(message))){output+=escapeHtml(message.slice(pos,m.index));output+=`<mark class="risk-mark" title="Needs review: unverified claim">${escapeHtml(m[0])}</mark>`;pos=m.index+m[0].length;if(!m[0].length)break}return output+escapeHtml(message.slice(pos))}
function minutes(time){const [h,m]=String(time||'00:00').split(':').map(Number);return h*60+m}
function eventEnd(e){return e.endTime&&minutes(e.endTime)>minutes(e.time)?minutes(e.endTime):minutes(e.time)+60}
function dateConflicts(item){if(!item?.calendarDate||!item?.calendarTime)return [];const start=minutes(item.calendarTime),end=start+(item.calendarDuration||60);return state.calendar.filter(e=>e.date===item.calendarDate&&minutes(e.time)<end&&eventEnd(e)>start)}
function calendarContext(item){if(!item?.calendarDate)return '';const overlap=dateConflicts(item),date=new Date(item.calendarDate+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});const end=minutes(item.calendarTime)+(item.calendarDuration||60);const endLabel=`${String(Math.floor(end/60)).padStart(2,'0')}:${String(end%60).padStart(2,'0')}`;return `<div class="calendar-insight"><div class="insight-heading">▦ Local calendar check <span class="badge-status simulated">DEMO DATA</span></div>${overlap.length?`<p><strong>Possible time conflict on ${escapeHtml(date)}, ${escapeHtml(item.calendarTime)}–${endLabel}.</strong></p><p>${overlap.map(e=>escapeHtml(e.title)+' ('+escapeHtml(e.time)+'–'+escapeHtml(e.endTime||'60 min assumed')+')').join(', ')} overlaps with the requested slot.</p><p class="insight-note">Local events are compared by overlapping time intervals. No real calendar is connected and this does not establish your intentions.</p><button class="btn secondary" data-${item.id.startsWith('em')?'email-action="calendar-reply"':'action="calendar-reply"'}>✦ Draft calendar-aware reply</button>`:`<p>No overlapping local event found for ${escapeHtml(date)}, ${escapeHtml(item.calendarTime)}–${endLabel}.</p><p class="insight-note">An empty demo calendar does not prove availability. Please confirm before agreeing.</p>`}<button class="calendar-link" data-goto="calendar">Open calendar →</button></div>`}
function calendarReply(item,tone){const conflict=dateConflicts(item)[0];if(!conflict)return 'I will check my calendar and confirm whether I can attend.';if(tone==='Friendly')return `Thanks for inviting me! I already have ${conflict.title} scheduled at that time. Could we find another slot?`;if(tone==='Concise')return 'I have a calendar conflict at that time. Could we reschedule?';return `Thank you for the invitation. My calendar shows ${conflict.title} at that time. Could we arrange an alternative slot?`}
function riskPanel(item,needsReview){if(!needsReview)return '';const [title,explanation]=riskNotes[item.kind]||['Unverified intent','The suggestion may not reflect your actual decision.'];return `<div class="why-review"><div class="why-review-title">◎ Why does this need review?</div><strong>${escapeHtml(title)}</strong><p>${escapeHtml(explanation)}</p><small>Rule-based demonstration · not a measured AI confidence score</small></div>`}
function compactReview(item,isUncertain,clar){
  // Clarification resolves what the user intends, even if they are still undecided.
  if(item.uncertain && clar==='unsure'){
    return `<div class="review-inline info-inline" role="status"><span class="review-icon">i</span><span><strong>Uncertainty acknowledged</strong><small>Your decision is not confirmed. The suggested reply reflects this without making a commitment.</small><details class="review-detail"><summary>Why this status?</summary><span>You selected “I'm not sure yet”. The demo keeps your uncertainty visible without treating it as an error.</span></details></span></div>`;
  }
  if(item.uncertain && (clar==='yes' || clar==='no')){
    return `<div class="review-inline safe-inline" role="status"><span class="review-icon">✓</span><span><strong>Intention confirmed</strong><small>Your choice has updated the suggested reply. Review or edit it before sending.</small></span></div>`;
  }
  if(!isUncertain){
    return `<div class="review-inline safe-inline" role="status"><span class="review-icon">✓</span><span><strong>Ready to review</strong><small>No clarification needed for this message.</small></span></div>`;
  }
  const [title,explanation]=riskNotes[item.kind]||['Unverified intent','The suggestion may not reflect your actual decision.'];
  return `<div class="review-inline" role="status"><span class="review-icon">!</span><span><strong>${escapeHtml(title)}</strong><small>${escapeHtml(explanation)}</small><details class="review-detail"><summary>Why review?</summary><span>Rule-based scenario: this is not an AI confidence score. Check the suggestion before sending.</span></details></span></div>`;
}
const state={page:'messages',selected:'alex',tone:'Professional',clarifications:{},editing:false,draft:'',customDraft:'',rejected:{},conversations:structuredClone([...initialConversations,...extraConversations]),emails:structuredClone(initialEmails),selectedEmail:'em1',emailClarifications:{},emailRegenerated:{},emailRejected:{},emailEditing:false,emailDraft:'',emailCustomDraft:'',emailSent:[],emailTone:'Professional',activity:[{text:'Prototype opened: SmartReply simulation ready',when:'Just now',type:'green'}],sent:[],regenerated:{},settings:{clarification:'selective',confirm:false},calendar:[],viewMonth:new Date().getMonth(),viewYear:new Date().getFullYear(),selectedDate:localDate(new Date()),profile:{name:'My workspace',email:'demo@smartreply.local',role:'Product Designer',status:'Available',initials:'FD'},notifications:[]};
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
const $=s=>document.querySelector(s),escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function current(){return state.conversations.find(x=>x.id===state.selected)}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function activity(msg,type='purple'){state.activity.unshift({text:msg,when:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),type});state.notifications.unshift({text:msg,at:new Date().toLocaleString()});saveDemo();}
function selectedSuggestion(){const c=current(),clar=state.clarifications[c.id];let replies=clar?c.clarified?.[clar]:c.responses;let txt=replies?.[state.tone]||c.responses[state.tone];if(state.regenerated[c.id])txt=state.regenerated[c.id];return txt}
function heading(label,title,subtitle,button=''){return `<div class="page-heading"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p class="subtle">${subtitle}</p></div>${button}</div>`}
function avatar(c,size=''){return `<span class="person-avatar" style="background:${c.color};${size}">${c.initials}</span>`}
function render(){document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));$('#page-title').textContent=({dashboard:'Overview',messages:'Messages',activity:'Activity',calendar:'Calendar',contacts:'Contacts',settings:'Settings',email:'Email'})[state.page];const renderers={dashboard:renderDashboard,messages:renderMessages,activity:renderActivity,calendar:renderCalendar,contacts:renderContacts,settings:renderSettings,email:renderEmail};$('#page-content').innerHTML=renderers[state.page]();$('#unread-count').textContent=String(state.conversations.filter(c=>c.uncertain&&!state.clarifications[c.id]).length);document.querySelectorAll('.avatar,.profile-avatar').forEach(el=>el.textContent=state.profile.initials);const p=document.querySelector('.profile strong');if(p)p.textContent=state.profile.name;const eb=$('#email-count');if(eb)eb.textContent=String(state.emails.filter(m=>m.uncertain&&!state.emailClarifications[m.id]).length);}
function renderMessages(){const c=current(),clar=state.clarifications[c.id],needsReview=c.uncertain&&!clar,stillUncertain=c.uncertain&&clar==='unsure', suggestion=state.rejected[c.id]?'Suggestion dismissed. Write your own reply below or select Regenerate.':selectedSuggestion(),alreadySent=!state.rejected[c.id]&&state.sent.some(x=>x.id===c.id&&x.text===selectedSuggestion());return `${heading('COMMUNICATE WITH CONFIDENCE','Your messages','A calmer, more thoughtful way to communicate with AI assistance.','<button class="btn secondary" data-action="new-message">＋ New message</button>')}<div class="message-layout"><section class="panel"><div class="panel-header"><h2>Conversations</h2><span class="count-pill">${state.conversations.length} chats</span></div><label class="search-field">⌕ <input id="conversation-search" placeholder="Search conversations..." aria-label="Search conversations"></label><div id="conversation-list">${conversationRows()}</div></section><section class="panel chat-panel"><div class="chat-header"><div class="chat-header-info">${avatar(c)}<div><strong>${escapeHtml(c.name)}</strong><small><span style="color:#3fba91">●</span> ${escapeHtml(c.role)}</small></div></div><span style="color:#b1b4c2">⋯</span></div><div class="chat-body" id="chat-body"><div class="date-divider">TODAY</div><div class="bubble-row"><div class="bubble">${escapeHtml(c.message)}<small>${escapeHtml(c.time)}</small></div></div>${state.sent.filter(s=>s.id===c.id).map(s=>`<div class="bubble-row mine"><div class="bubble mine">${escapeHtml(s.text)}<small>${escapeHtml(s.time)} · Sent (simulation)</small></div></div>`).join('')}</div><div class="chat-footer"><form id="chat-compose" class="composer"><textarea id="manual-message" rows="1" placeholder="Write a message or use SmartReply..." aria-label="Compose message">${escapeHtml(state.customDraft)}</textarea><div class="composer-actions"><button class="send-btn" aria-label="Send manual message" title="Send in prototype">➤</button></div></form></div></section><section class="panel ai-panel"><div class="ai-header"><div class="ai-title"><h2>✦ SmartReply Assistant</h2><span class="spark">✦</span></div><p>AI-inspired suggestions, always in your control.</p></div><div class="ai-content"><div class="small-label">CHOOSE YOUR TONE</div><div class="tone-selector">${['Friendly','Professional','Concise'].map(t=>`<button class="tone ${state.tone===t?'active':''}" data-tone="${t}">${t}</button>`).join('')}</div><div class="suggestion"><div class="suggestion-title">Suggested reply <span class="badge-status simulated" style="margin-left:auto">SIMULATED</span></div>${state.editing?`<textarea id="edit-suggestion" aria-label="Edit suggested reply">${escapeHtml(state.draft)}</textarea>`:`<p>${(needsReview||stillUncertain)&&!state.rejected[c.id]?riskMarkup(suggestion,c.kind):escapeHtml(suggestion)}</p>`}</div>${compactReview(c,needsReview||stillUncertain,clar)}${c.uncertain&&needsReview&&state.settings.clarification==='selective'?`<div class="clarification"><strong>✳ A quick clarification</strong><p>${escapeHtml(c.question)}</p>${c.choices.map(([val,label])=>`<button class="choice" data-choice="${val}">${escapeHtml(label)}</button>`).join('')}</div>`:''}${calendarContext(c)}${c.uncertain&&clar?`<button class="btn outline" style="width:100%;margin-bottom:10px" data-action="reset-clarification">↺ Change clarification</button>`:''}<div class="action-grid"><button class="btn outline" data-action="${state.editing?'save-edit':'edit'}">${state.editing?'✓ Save edit':'✎ Edit reply'}</button><button class="btn outline" data-action="regenerate">↻ Regenerate</button><button class="btn outline" data-action="reject">✕ Reject</button><button class="btn primary" data-action="send-suggestion" ${alreadySent?'disabled title="Already sent — edit or regenerate for a new reply"':''}>${alreadySent?'✓ Sent':'➤ Send reply'}</button></div><p class="helper">Prototype only: suggestions and uncertainty states are rule-based simulations. No real AI model or message delivery is connected.</p></div></section></div>`}
function conversationRows(query=''){return state.conversations.filter(c=>(c.name+' '+c.message).toLowerCase().includes(query.toLowerCase())).map(c=>`<div class="conversation ${state.selected===c.id?'active':''}" data-select="${c.id}">${avatar(c)}<div class="conversation-main"><div class="conversation-row"><strong>${escapeHtml(c.name)}</strong><time>${escapeHtml(c.time)}</time></div><div class="conversation-role">${escapeHtml(c.role)}</div><p>${escapeHtml(c.message)}</p></div>${c.uncertain?'<span class="unread-dot"></span>':''}</div>`).join('')||'<p class="empty">No matching conversations</p>'}

function currentEmail(){return state.emails.find(m=>m.id===state.selectedEmail)||state.emails[0]}
function suggestedEmail(){const m=currentEmail(),clar=state.emailClarifications[m.id],base=clar?m.clarified?.[clar]:m.responses;return state.emailRegenerated[m.id]||base?.[state.emailTone]||m.responses[state.emailTone]}
function resetEmailPanel(){state.emailEditing=false;state.emailDraft='';state.emailCustomDraft=''}
function renderEmail(){const m=currentEmail(),clar=state.emailClarifications[m.id],unverified=m.uncertain&&!clar,stillUncertain=m.uncertain&&clar==='unsure',reply=state.emailRejected[m.id]?'Suggestion dismissed. Compose your own email or regenerate.':suggestedEmail(),alreadySent=!state.emailRejected[m.id]&&state.emailSent.some(x=>x.id===m.id&&x.text===suggestedEmail());return `${heading('SMARTER EMAIL COMMUNICATION','Email inbox','Sample incoming emails with the same review-first SmartReply workflow.','<span class="badge-status simulated">DEMO INBOX · NO REAL EMAIL DELIVERY</span>')}<div class="email-layout"><section class="panel email-inbox"><div class="panel-header"><h2>Inbox</h2><span class="count-pill">${state.emails.length} emails</span></div><label class="search-field">⌕ <input id="email-search" placeholder="Search email..." aria-label="Search emails"></label><div id="email-list">${emailRows()}</div></section><section class="panel email-detail"><div class="email-detail-head"><div class="eyebrow">INCOMING EMAIL</div><h2>${escapeHtml(m.subject)}</h2><div class="email-from">${avatar(m)}<div><strong>${escapeHtml(m.name)}</strong><small>${escapeHtml(m.address)} · ${escapeHtml(m.time)}</small></div></div></div><div class="email-body">${escapeHtml(m.message)}</div>${state.emailSent.filter(x=>x.id===m.id).map(x=>`<div class="email-sent"><strong>↳ Your sent reply · simulated</strong><p>${escapeHtml(x.text)}</p><small>${escapeHtml(x.time)}</small></div>`).join('')}<div class="email-compose"><div class="small-label">WRITE YOUR OWN EMAIL</div><form id="email-compose-form"><textarea id="email-manual" rows="4" placeholder="Write a reply to ${escapeHtml(m.name)}...">${escapeHtml(state.emailCustomDraft)}</textarea><button class="btn secondary" type="submit">➤ Send email (demo)</button></form></div></section><section class="panel ai-panel"><div class="ai-header"><div class="ai-title"><h2>✦ SmartReply for Email</h2><span class="spark">✦</span></div><p>Check meaning before making a commitment.</p></div><div class="ai-content"><div class="small-label">CHOOSE YOUR TONE</div><div class="tone-selector">${['Friendly','Professional','Concise'].map(t=>`<button class="tone ${state.emailTone===t?'active':''}" data-email-tone="${t}">${t}</button>`).join('')}</div><div class="suggestion"><div class="suggestion-title">Suggested email <span class="badge-status simulated" style="margin-left:auto">SIMULATED</span></div>${state.emailEditing?`<textarea id="email-suggestion-edit" aria-label="Edit email suggestion">${escapeHtml(state.emailDraft)}</textarea>`:`<p>${(unverified||stillUncertain)&&!state.emailRejected[m.id]?riskMarkup(reply,m.kind||'delivery'):escapeHtml(reply)}</p>`}</div>${compactReview(m,unverified||stillUncertain,clar)}${unverified&&state.settings.clarification==='selective'?`<div class="clarification"><strong>✳ Quick clarification</strong><p>${escapeHtml(m.question)}</p>${m.choices.map(([val,label])=>`<button class="choice" data-email-choice="${val}">${escapeHtml(label)}</button>`).join('')}</div>`:''}${calendarContext(m)}${clar?'<button class="btn outline" data-email-action="reset" style="width:100%;margin-bottom:10px">↺ Change clarification</button>':''}<div class="action-grid"><button class="btn outline" data-email-action="${state.emailEditing?'save-edit':'edit'}">${state.emailEditing?'✓ Save edit':'✎ Edit email'}</button><button class="btn outline" data-email-action="regenerate">↻ Regenerate</button><button class="btn outline" data-email-action="reject">✕ Reject</button><button class="btn primary" data-email-action="send" ${alreadySent?'disabled title="Already sent — edit or regenerate for a new reply"':''}>${alreadySent?'✓ Sent':'➤ Send reply'}</button></div><p class="helper">These are sample emails. Reply suggestions and uncertainty warnings are rule-based simulations. No email account is connected.</p></div></section></div>`}
function emailRows(q=''){return state.emails.filter(m=>(m.name+' '+m.subject+' '+m.message).toLowerCase().includes(q.toLowerCase())).map(m=>`<button class="email-row ${state.selectedEmail===m.id?'active':''}" data-select-email="${m.id}">${avatar(m)}<span class="email-row-main"><span class="email-row-title"><strong>${escapeHtml(m.name)}</strong><time>${escapeHtml(m.time)}</time></span><b>${escapeHtml(m.subject)}</b><small>${escapeHtml(m.message)}</small></span>${m.uncertain&&!state.emailClarifications[m.id]?'<i class="unread-dot"></i>':''}</button>`).join('')||'<p class="empty">No matching emails.</p>'}
function sendEmail(text){if(!text.trim())return toast('Write an email before sending.');const m=currentEmail();if(state.emailSent.some(x=>x.id===m.id&&x.text===text.trim()))return toast('This email reply has already been sent. Edit it or create another reply.');state.emailSent.push({id:m.id,text:text.trim(),time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})});state.emailCustomDraft='';state.emailEditing=false;activity(`Email reply sent to ${m.name} (simulation)`,'green');saveDemo();render();toast('Email sent in prototype ✓')}
function renderDashboard(){return `${heading('YOUR WORKSPACE','Good to see you 👋','Thoughtful replies start with meaningful control.','<button class="btn primary" data-goto="messages">Open messages →</button>')}<div class="hero"><div><div class="eyebrow" style="color:#ddd7ff">SMARTER COMMUNICATION</div><h2>Say what you mean.<br>Stay in control.</h2><p>SmartReply helps you review AI-suggested messages, clarify uncertain intentions, and choose the reply that feels right.</p><button class="btn" style="color:#5a4bca;background:#fff" data-goto="messages">Explore SmartReply →</button></div><div class="hero-art">✦</div></div><div class="metrics"><div class="card metric"><div class="icon">▤</div><strong>${state.conversations.length}</strong><small>Conversations</small></div><div class="card metric"><div class="icon">⚠</div><strong>${state.conversations.filter(c=>c.uncertain&&!state.clarifications[c.id]).length}</strong><small>Unreviewed uncertain replies</small></div><div class="card metric"><div class="icon">✓</div><strong>${state.sent.length}</strong><small>Replies sent in simulation</small></div></div><div class="two-cols"><div class="card"><h2>Recent activity</h2>${activityRows(state.activity.slice(0,4))}<button class="btn secondary" data-goto="activity" style="margin-top:14px">View all activity →</button></div><div class="card"><h2>How SmartReply works</h2>${[['✦','Suggest','Draft a reply in three tones.'],['⚠','Clarify','Ask when intent is unknown.'],['✓','Control','Edit, reject, or approve before sending.']].map(x=>`<div class="feature-row"><div class="feature-icon">${x[0]}</div><div><strong>${x[1]}</strong><p>${x[2]}</p></div></div>`).join('')}</div></div>`}
function activityRows(list){return list.map(a=>`<div class="activity-row"><i class="event-dot ${a.type}"></i><span>${escapeHtml(a.text)}</span><time>${a.when}</time></div>`).join('')}
function renderActivity(){return `${heading('YOUR WORKSPACE','Activity center','Review simulated actions and recent events.')}<div class="card"><h2>Recent events</h2>${activityRows(state.activity)}</div>`}
function oldRenderCalendar(){return `${heading('STAY ORGANIZED','Your calendar','Sample events for the interface demonstration.','<button class="btn secondary" data-action="add-event">＋ Add event</button>')}<div class="two-cols"><div class="card"><h2>Upcoming events <span class="badge-status simulated">SAMPLE DATA</span></h2>${state.calendar.map(e=>`<div class="calendar-row"><i class="event-dot"></i><span><strong>${escapeHtml(e.title)}</strong><small style="display:block;color:#9ba0b1;margin-top:4px">${escapeHtml(e.with)}</small></span><time>${escapeHtml(e.date)}</time></div>`).join('')}</div><div class="card"><h2>Calendar & uncertainty</h2><p class="subtle" style="line-height:1.9">SmartReply does not currently check calendar availability. A proposed commitment to a meeting is therefore marked for clarification instead of being treated as verified.</p><span class="badge-status simulated">Real calendar integration: planned</span></div></div>`}
function renderCalendar(){
 const first=new Date(state.viewYear,state.viewMonth,1),days=new Date(state.viewYear,state.viewMonth+1,0).getDate(),offset=(first.getDay()+6)%7;
 const title=first.toLocaleDateString('en-GB',{month:'long',year:'numeric'});
 const eventList=state.calendar.filter(e=>e.date===state.selectedDate).sort((a,b)=>a.time.localeCompare(b.time));
 const cells=Array.from({length:Math.ceil((offset+days)/7)*7},(_,i)=>{const day=i-offset+1;if(day<1||day>days)return '<div class="day-cell outside"></div>';const date=localDate(new Date(state.viewYear,state.viewMonth,day)),count=state.calendar.filter(e=>e.date===date).length;return `<button class="day-cell ${date===state.selectedDate?'chosen':''} ${date===localDate(new Date())?'today':''}" data-day="${date}"><b>${day}</b>${count?`<span class="day-count">${count} event${count>1?'s':''}</span>`:''}</button>`}).join('');
 return `${heading('STAY ORGANIZED','Your calendar','Manage local events and explore calendar-informed SmartReply suggestions.','<div class="calendar-top-actions"><button class="btn outline" data-action="demo-conflict">＋ Add demo conflict</button><button class="btn primary" data-action="add-event">＋ New event</button></div>')}<div class="calendar-layout"><section class="card calendar-main"><div class="cal-head"><h2>${title}</h2><div class="cal-nav"><button class="btn outline" data-action="calendar-prev" aria-label="Previous month">‹</button><button class="btn outline" data-action="calendar-today">Today</button><button class="btn outline" data-action="calendar-next" aria-label="Next month">›</button></div></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<div class="weekday">${x}</div>`).join('')}${cells}</div></section><aside class="card calendar-side"><div class="cal-head"><div><div class="eyebrow">SELECTED DAY</div><h2>${new Date(state.selectedDate+'T12:00:00').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'})}</h2></div></div>${eventList.length?eventList.map(e=>`<div class="event-card"><div class="event-time">◷ ${escapeHtml(e.time)}–${escapeHtml(e.endTime||`${String((Number(e.time.slice(0,2))+1)%24).padStart(2,"0")}:${e.time.slice(3)}`)}</div><strong>${escapeHtml(e.title)}</strong><p>${escapeHtml(e.with||'Personal event')}</p><div class="event-actions"><button class="btn outline" data-edit-event="${e.id}">Edit</button><button class="btn outline" data-delete-event="${e.id}">Delete</button></div></div>`).join(''):'<div class="empty-state">☀<p>No events planned for this day.</p><small>Select another date or add a new event.</small></div>'}<button class="btn secondary" data-action="add-event" style="width:100%;margin-top:16px">＋ Add event for this day</button><p class="helper">Local demonstration calendar. No Google / Outlook calendar connection.</p></aside></div>`;
}
function renderContacts(){return `${heading('PEOPLE','Your contacts','People available in this sample workspace.','<button class="btn secondary" data-action="add-contact">＋ Add contact</button>')}<div class="card"><h2>Team directory</h2>${state.conversations.map(c=>`<div class="contact-row">${avatar(c)}<span><strong>${escapeHtml(c.name)}</strong><small style="display:block;color:#9ba0b1;margin-top:4px">${escapeHtml(c.role)}</small></span><button class="btn secondary" data-open-chat="${c.id}">Message →</button></div>`).join('')}</div>`}
function renderSettings(){return `${heading('PERSONALIZATION','Settings','Control how the interactive simulation behaves.')}<div class="card"><h2>SmartReply preferences</h2><div class="settings-row"><div><strong>Clarification policy</strong><small>Choose whether to ask when a simulated intent is uncertain.</small></div><select id="clarification-policy"><option value="selective" ${state.settings.clarification==='selective'?'selected':''}>Selective questions</option><option value="never" ${state.settings.clarification==='never'?'selected':''}>Warnings only</option></select></div><div class="settings-row"><div><strong>Confirm before sending</strong><small>Only your explicit Send action places a reply in the simulated conversation.</small></div><span class="badge-status">Manual send only</span></div><div class="settings-row"><div><strong>AI model</strong><small>Fixed scenarios and deterministic reply templates.</small></div><span class="badge-status simulated">Simulated</span></div><div class="settings-row"><div><strong>Real-world integrations</strong><small>Local contacts, notifications and calendar events; no external account sync or message delivery.</small></div><span class="badge-status simulated">Not implemented</span></div><button class="btn outline" style="margin-top:24px" data-action="reset-demo">Reset demo</button></div>`}
function resetSuggestionState(){state.editing=false;state.draft='';state.regenerated[state.selected]=null;state.rejected[state.selected]=false;state.customDraft=''}
function send(text){if(!text.trim())return toast('Write a reply before sending.');if(state.sent.some(x=>x.id===state.selected&&x.text===text.trim()))return toast('This reply has already been sent. Edit it or choose a new suggestion.');state.sent.push({id:state.selected,text:text.trim(),time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})});activity(`Reply sent to ${current().name} (simulation)`,'green');state.customDraft='';state.editing=false;saveDemo();toast('Message sent in this demo ✓');render();$('#chat-body')?.scrollTo(0,99999)}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-page]');if(nav){state.page=nav.dataset.page;render();return}const goto=e.target.closest('[data-goto]');if(goto){state.page=goto.dataset.goto;render();return}const open=e.target.closest('[data-open-chat]');if(open){state.page='messages';state.selected=open.dataset.openChat;resetSuggestionState();render();return}const contact=e.target.closest('[data-select]');if(contact){state.selected=contact.dataset.select;resetSuggestionState();render();return}const tone=e.target.closest('[data-tone]');if(tone){state.tone=tone.dataset.tone;state.editing=false;state.regenerated[state.selected]=null;state.rejected[state.selected]=false;activity(`Tone changed to ${state.tone}`);render();return}const choice=e.target.closest('[data-choice]');if(choice){state.clarifications[state.selected]=choice.dataset.choice;state.editing=false;state.regenerated[state.selected]=null;activity(`Clarification answered for ${current().name}`,'orange');render();toast('Suggestion updated using your answer');return}const day=e.target.closest('[data-day]');if(day){state.selectedDate=day.dataset.day;render();return}const editEvent=e.target.closest('[data-edit-event]');if(editEvent){openEventModal(editEvent.dataset.editEvent);return}const deleteEvent=e.target.closest('[data-delete-event]');if(deleteEvent){state.calendar=state.calendar.filter(x=>x.id!==deleteEvent.dataset.deleteEvent);activity('Calendar event deleted','orange');saveDemo();render();toast('Event deleted');return}const emailSel=e.target.closest('[data-select-email]');if(emailSel){state.selectedEmail=emailSel.dataset.selectEmail;resetEmailPanel();state.page='email';render();return}const emailTone=e.target.closest('[data-email-tone]');if(emailTone){state.emailTone=emailTone.dataset.emailTone;state.emailEditing=false;state.emailRegenerated[state.selectedEmail]='';state.emailRejected[state.selectedEmail]=false;render();return}const emailChoice=e.target.closest('[data-email-choice]');if(emailChoice){state.emailClarifications[state.selectedEmail]=emailChoice.dataset.emailChoice;state.emailRegenerated[state.selectedEmail]='';state.emailEditing=false;activity(`Email clarification answered for ${currentEmail().name}`,'orange');render();toast('Email suggestion updated');return}const emailAction=e.target.closest('[data-email-action]');if(emailAction){const id=state.selectedEmail;switch(emailAction.dataset.emailAction){case 'calendar-reply':state.emailRejected[id]=false;state.emailRegenerated[id]=calendarReply(currentEmail(),state.emailTone);state.emailEditing=false;activity('Calendar-aware email reply drafted (simulation)');render();toast('Calendar-aware draft ready to review');break;case 'edit':state.emailRejected[id]=false;state.emailEditing=true;state.emailDraft=suggestedEmail();render();break;case 'save-edit':state.emailRegenerated[id]=$('#email-suggestion-edit')?.value||'';state.emailEditing=false;activity('Email suggestion edited');render();toast('Edited email ready');break;case 'regenerate':state.emailRejected[id]=false;state.emailRegenerated[id]=currentEmail().uncertain&&!state.emailClarifications[id]?'Thank you for your message. I will verify the details before confirming.':`Thank you for contacting me. ${suggestedEmail()}`;state.emailEditing=false;activity('Alternative email suggestion generated (simulation)');render();toast('Alternative email drafted');break;case 'reject':state.emailRejected[id]=true;state.emailRegenerated[id]='';state.emailEditing=false;render();toast('Email suggestion dismissed');$('#email-manual')?.focus();break;case 'reset':delete state.emailClarifications[id];state.emailRegenerated[id]='';state.emailEditing=false;render();break;case 'send':if(state.emailRejected[id]){toast('Write your own email or regenerate');$('#email-manual')?.focus();break}sendEmail(state.emailEditing?$('#email-suggestion-edit')?.value||'':suggestedEmail());break;}return}const action=e.target.closest('[data-action]');if(!action)return;switch(action.dataset.action){case 'calendar-reply':state.rejected[state.selected]=false;state.regenerated[state.selected]=calendarReply(current(),state.tone);state.editing=false;activity('Calendar-aware chat reply drafted (simulation)');render();toast('Calendar-aware draft ready to review');break;case 'edit':state.rejected[state.selected]=false;state.editing=true;state.draft=selectedSuggestion();render();break;case 'save-edit':state.draft=$('#edit-suggestion')?.value||'';state.regenerated[state.selected]=state.draft;state.editing=false;activity('Suggested reply manually edited');render();toast('Your edited reply is ready');break;case 'regenerate':{state.rejected[state.selected]=false;const c=current();const txt=selectedSuggestion();const alternate=c.uncertain&&!state.clarifications[c.id]?'I will confirm the details before making a commitment.':`Thanks for your message. ${txt}`;state.regenerated[c.id]=alternate;state.editing=false;activity('Alternative reply generated (simulation)');render();toast('Alternative suggestion generated');break}case 'reject':state.rejected[state.selected]=true;state.regenerated[state.selected]='';state.editing=false;state.customDraft='';activity(`Suggestion rejected for ${current().name}`,'orange');render();toast('Suggestion rejected · write your own reply below');$('#manual-message')?.focus();break;case 'reset-clarification':delete state.clarifications[state.selected];state.regenerated[state.selected]=null;state.editing=false;render();break;case 'send-suggestion':{if(state.rejected[state.selected]){toast('Please write a message or regenerate the suggestion');$('#manual-message')?.focus();break}const value=state.editing?$('#edit-suggestion')?.value:selectedSuggestion();send(value||'');break}case 'new-message':toast('Choose a contact in the directory to start a sample conversation');state.page='contacts';render();break;case 'demo-conflict':{if(!state.calendar.some(e=>e.id==='sample-calendar-conflict'))state.calendar.push({id:'sample-calendar-conflict',date:'2026-11-23',time:'14:00',endTime:'15:00',title:'Design review',with:'Product Team'});state.selectedDate='2026-11-23';state.viewMonth=10;state.viewYear=2026;activity('Sample 23 November calendar conflict added','green');render();toast('Demo conflict created for 23 November at 14:00');break}case 'add-event':openEventModal();break;case 'calendar-prev':changeMonth(-1);break;case 'calendar-next':changeMonth(1);break;case 'calendar-today':state.selectedDate=localDate(new Date());state.viewMonth=new Date().getMonth();state.viewYear=new Date().getFullYear();render();break;case 'add-contact':openContactModal();break;case 'reset-demo':if(confirm('Reset demo messages, events and preferences?')){localStorage.removeItem('smartreply-demo-v2');location.reload()}break;}});
document.addEventListener('input',e=>{if(e.target.id==='email-search')$('#email-list').innerHTML=emailRows(e.target.value);if(e.target.id==='email-manual')state.emailCustomDraft=e.target.value;if(e.target.id==='conversation-search')$('#conversation-list').innerHTML=conversationRows(e.target.value);if(e.target.id==='manual-message')state.customDraft=e.target.value});
document.addEventListener('change',e=>{if(e.target.id==='clarification-policy'){state.settings.clarification=e.target.value;activity('Clarification policy updated');toast('Clarification preference saved')}});
document.addEventListener('submit',e=>{if(e.target.id==='email-compose-form'){e.preventDefault();sendEmail($('#email-manual').value)}if(e.target.id==='chat-compose'){e.preventDefault();send($('#manual-message').value)}});
$('#global-search').addEventListener('click',()=>{state.page='messages';render();$('#conversation-search')?.focus()});$('#notification-btn').addEventListener('click',()=>openNotifications());document.querySelector('.profile').addEventListener('click',openProfile);document.querySelector('.avatar').addEventListener('click',openProfile);document.querySelector('.workspace-switch').addEventListener('click',openProfile);initializeDemo();render();


/* Additional interactive workspace features. All data stays in this browser. */
function saveDemo(){try{localStorage.setItem('smartreply-demo-v2',JSON.stringify({sent:state.sent,emails:state.emails,emailSent:state.emailSent,emailClarifications:state.emailClarifications,calendar:state.calendar,profile:state.profile,settings:state.settings,conversations:state.conversations,activity:state.activity,clarifications:state.clarifications,notifications:state.notifications}))}catch(e){/* browsers may disable storage for local files */}}
function initializeDemo(){
 const today=new Date(),tomorrow=new Date(today.getFullYear(),today.getMonth(),today.getDate()+1),friday=new Date(today);friday.setDate(today.getDate()+((5-today.getDay()+7)%7||7));
 state.calendar=[{id:'sample-calendar-conflict',date:'2026-11-23',time:'14:00',endTime:'15:00',title:'Design review',with:'Product Team'},{id:'sample-1',date:localDate(today),time:'11:00',endTime:'11:30',title:'Product stand-up',with:'Design Team'},{id:'sample-2',date:localDate(tomorrow),time:'15:00',endTime:'16:00',title:'Client presentation',with:'Marketing'},{id:'sample-3',date:localDate(friday),time:'09:30',endTime:'10:00',title:'Weekly check-in',with:'Project Team'}];
 try{const saved=JSON.parse(localStorage.getItem('smartreply-demo-v2')||'null');if(saved){for(const key of ['sent','emails','emailSent','emailClarifications','calendar','profile','settings','conversations','activity','clarifications','notifications'])if(saved[key]!==undefined)state[key]=saved[key]}if(!state.conversations.some(c=>c.id===calendarChatDemo.id))state.conversations.unshift(structuredClone(calendarChatDemo));if(!state.emails.some(m=>m.id===calendarEmailDemo.id))state.emails.unshift(structuredClone(calendarEmailDemo));for(const c of extraConversations){if(!state.conversations.some(existing=>existing.id===c.id))state.conversations.push(structuredClone(c));}}catch(e){/* defaults retained */}
}
function changeMonth(amount){const d=new Date(state.viewYear,state.viewMonth+amount,1);state.viewMonth=d.getMonth();state.viewYear=d.getFullYear();state.selectedDate=localDate(d);render()}
function openModal(body){closeModal();const overlay=document.createElement('div');overlay.className='modal-backdrop';overlay.id='workspace-modal';overlay.innerHTML=`<div class="workspace-modal" role="dialog" aria-modal="true">${body}</div>`;document.body.append(overlay);overlay.addEventListener('click',e=>{if(e.target===overlay||e.target.closest('[data-close-modal]'))closeModal()});document.addEventListener('keydown',escModal);overlay.querySelector('input,select,button')?.focus()}
function escModal(e){if(e.key==='Escape')closeModal()}
function closeModal(){document.querySelector('#workspace-modal')?.remove();document.removeEventListener('keydown',escModal)}
function openEventModal(id){const e=state.calendar.find(e=>e.id===id),date=e?.date||state.selectedDate;openModal(`<div class="modal-head"><div><div class="eyebrow">CALENDAR</div><h2>${e?'Edit event':'Create an event'}</h2></div><button class="iconbtn" data-close-modal aria-label="Close">×</button></div><form id="event-form" class="modal-form"><label>Event title<input name="title" maxlength="90" required placeholder="e.g. Team meeting" value="${escapeHtml(e?.title||'')}"></label><div class="form-row"><label>Date<input name="date" type="date" required value="${date}"></label><label>Start time<input name="time" type="time" required value="${e?.time||'10:00'}"></label><label>End time<input name="endTime" type="time" required value="${e?.endTime||'11:00'}"></label></div><label>Participants / notes<input name="with" placeholder="e.g. Marketing team" value="${escapeHtml(e?.with||'')}"></label><p class="helper">Events are saved locally in your browser for this demo.</p><div class="modal-footer"><button class="btn outline" type="button" data-close-modal>Cancel</button><button class="btn primary" type="submit">${e?'Save changes':'Create event'}</button></div></form>`);document.querySelector('#event-form').addEventListener('submit',ev=>{ev.preventDefault();const fd=new FormData(ev.currentTarget),item={id:e?.id||'evt-'+Date.now(),title:String(fd.get('title')).trim(),date:String(fd.get('date')),time:String(fd.get('time')),endTime:String(fd.get('endTime')),with:String(fd.get('with')).trim()};if(!item.title)return;if(minutes(item.endTime)<=minutes(item.time)){toast('End time must be later than start time');return;}if(e)Object.assign(e,item);else state.calendar.push(item);state.selectedDate=item.date;const d=new Date(item.date+'T12:00:00');state.viewYear=d.getFullYear();state.viewMonth=d.getMonth();activity(e?'Calendar event updated':'Calendar event created','green');saveDemo();closeModal();render();toast(e?'Event updated':'Event added to calendar')})}
function openProfile(){const p=state.profile;openModal(`<div class="modal-head"><div><div class="eyebrow">YOUR ACCOUNT</div><h2>My profile</h2></div><button class="iconbtn" data-close-modal aria-label="Close">×</button></div><div class="profile-summary"><div class="big-avatar">${escapeHtml(p.initials)}</div><div><strong>${escapeHtml(p.name)}</strong><p>Local prototype profile · no account required</p></div></div><form id="profile-form" class="modal-form"><label>Display name<input name="name" maxlength="65" required value="${escapeHtml(p.name)}"></label><label>Email<input type="email" name="email" required value="${escapeHtml(p.email)}"></label><label>Role<input name="role" maxlength="65" value="${escapeHtml(p.role)}"></label><label>Availability<select name="status">${['Available','Busy','Away'].map(x=>`<option ${p.status===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="modal-footer"><button class="btn outline" type="button" data-close-modal>Cancel</button><button class="btn primary" type="submit">Save profile</button></div></form>`);document.querySelector('#profile-form').addEventListener('submit',ev=>{ev.preventDefault();const fd=new FormData(ev.currentTarget);state.profile.name=String(fd.get('name')).trim();state.profile.email=String(fd.get('email')).trim();state.profile.role=String(fd.get('role')).trim();state.profile.status=String(fd.get('status'));state.profile.initials=state.profile.name.split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase()||'ME';activity('Profile details updated','green');saveDemo();closeModal();render();toast('Profile saved')})}
function openContactModal(){openModal(`<div class="modal-head"><div><div class="eyebrow">PEOPLE</div><h2>Add a contact</h2></div><button class="iconbtn" data-close-modal aria-label="Close">×</button></div><form id="contact-form" class="modal-form"><label>Full name<input name="name" maxlength="65" required placeholder="Contact name"></label><label>Team / role<input name="role" maxlength="65" placeholder="e.g. Design Team"></label><label>First message<input name="message" maxlength="300" placeholder="e.g. Hi! Do you have a minute?"></label><div class="modal-footer"><button type="button" class="btn outline" data-close-modal>Cancel</button><button class="btn primary" type="submit">Add contact</button></div></form>`);document.querySelector('#contact-form').addEventListener('submit',ev=>{ev.preventDefault();const fd=new FormData(ev.currentTarget),name=String(fd.get('name')).trim();if(!name)return;const initials=name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase(),id='contact-'+Date.now();state.conversations.push({id,name,role:String(fd.get('role')).trim()||'Contact',initials,color:'#8c93da',time:'Today',message:String(fd.get('message')).trim()||'Hello!',uncertain:false,kind:'general',responses:{Friendly:'Hi! Great to hear from you 😊',Professional:'Hello, thank you for your message.',Concise:'Hello!'}});state.selected=id;state.page='messages';activity(`Contact ${name} added`,'green');saveDemo();closeModal();render();toast('Contact added — chat opened')})}
function openNotifications(){openModal(`<div class="modal-head"><div><div class="eyebrow">WORKSPACE UPDATES</div><h2>Notifications</h2></div><button class="iconbtn" data-close-modal aria-label="Close">×</button></div><div class="notifications-list">${state.notifications.length?state.notifications.slice(0,12).map(x=>`<div class="notification-row"><span>✦</span><div><strong>${escapeHtml(x.text)}</strong><small>${escapeHtml(x.at)}</small></div></div>`).join(''):'<p class="empty">No new notifications yet. Try editing a reply or creating an event.</p>'}</div><div class="modal-footer"><button class="btn outline" data-close-modal>Close</button><button class="btn primary" data-action="view-activity-modal">View activity</button></div>`);document.querySelector('[data-action="view-activity-modal"]').addEventListener('click',()=>{closeModal();state.page='activity';render()})}
